function firstUnique(text) {
  const count = new Map();
  for (const ch of text) count.set(ch, (count.get(ch) ?? 0) + 1);
  for (const ch of text) if (count.get(ch) === 1) return ch;
  return null;
}
```

For `swiss`, the function returns `w`.

```js
function areAnagrams(left, right) {
  left = left.toLowerCase();
  right = right.toLowerCase();
  if (left.length !== right.length) return false;
  const count = new Map();
  for (const ch of left) count.set(ch, (count.get(ch) ?? 0) + 1);
  for (const ch of right) {
    const remaining = count.get(ch) ?? 0;
    if (remaining === 0) return false;
    count.set(ch, remaining - 1);
  }
  return true;
}
```

This version is case-insensitive but intentionally keeps spaces and punctuation.

```js
function maxWindowSum(values, k) {
  if (k <= 0 || k > values.length) return null;
  let sum = values.slice(0, k).reduce((a, b) => a + b, 0);
  let best = sum;
  for (let right = k; right < values.length; right++) {
    sum += values[right] - values[right - k];
    best = Math.max(best, sum);
  }
  return best;
}
```

The outgoing index is always `right - k`.

```js
function rotateRight(values, k) {
  const n = values.length;
  if (n === 0) return [];
  k = ((k % n) + n) % n;
  return values.slice(n - k).concat(values.slice(0, n - k));
}
```

A normalized `k` of zero returns an equal copy of the original order.
